/**
 * The single per-user Truth Snapshot for a symbol. It COMPOSES the existing
canonical resolvers — chart feed (data state, price, data timestamps),
market-impact radar (news provider + events), the scanner signal, the
scalp/flame reads, and the timing read — into ONE object so every
scanner/chart/Ruby surface renders identical freshness, news state, price,
and component verdicts. Read-only: it never places, modifies, or closes a
trade, never gates execution, and never fabricates data — a blind or
failing source becomes an absent component (present:false), never a guess.
Freshness is exposed as the underlying DATA timestamps (lastCandleAt /
lastTickAt); the snapshot's own generatedAt is the build time, kept
separate. Actionable entry/stop/target levels are withheld when the saved
geometry has drifted too far from the current price.

 * @summary One Truth Snapshot for a symbol/timeframe (Task
 */
export const getMeMarketTruthPathSymbolMax = 64;

export const GetMeMarketTruthParams = zod.object({
  symbol: zod.coerce.string().min(1).max(getMeMarketTruthPathSymbolMax),
});

